arguments.command:
cd /app; cat > /tmp/fix.py <<'E'
import sys
root,which=sys.argv[1],sys.argv[2]
def sub(p,a,b):
    p=f"{root}/quayside/{p}"; s=open(p).read(); assert a in s,(p,a); open(p,'w').write(s.replace(a,b))
if which in("A","ALL"): sub('dedupe.py','    field = "idem_key"\n','    v = payload.get("v")\n    field = "idem" if v is not True and isinstance(v, int) and v >= 3 else "idem_key" if v == 2 else None\n'); sub('dedupe.py','    idem = payload.get(field)','    idem = payload.get(field) if field else None')
if which in("B","ALL"): sub('lease.py','cfg.visibility_ms // 3','job.visibility_ms // 3')
if which in("C","ALL"): sub('retry.py','''    msg["failures"] += 1
    if msg["failures"] >= job.max_attempts:
        return ("dead", "attempts-exhausted")
    if outcome == "throttled":
        return ("retry", now + retry_after_ms)
''','''    if outcome == "throttled":
        return ("retry", now + retry_after_ms)
    msg["failures"] += 1
    if msg["failures"] >= job.max_attempts:
        return ("dead", "attempts-exhausted")
''')
if which in("D","ALL"): sub('schema.py','''    known = set(REQUIRED[job_type]) | {"v", "sent_at", "idem", "idem_key"}
    extra = sorted(set(payload) - known)
    if extra:
        return f"unknown field {extra[0]}"
''','')
E
for n in A B C D ALL; do python3 /tmp/fix.py /tmp/w/$n $n; python3 tools/replay.py --pkg /tmp/w/$n --diff > /tmp/w/$n.out; echo $n; tail -1 /tmp/w/$n.out; done

